from lib import *
S = SS('n27')
steps = [
    step("Gin 的默认校验器是 go-playground/validator v10,延迟初始化:第一次校验时 validator.New(),并 SetTagName(\"binding\")——所以规则写在 binding 标签里,而不是 validator 标签。ValidateStruct 对指针、结构体、切片/数组(逐个元素)有分支,其它类型直接返回 nil。", t=tl(S(1)), mark=lidx(S(1), 'validator.New()', 'SetTagName("binding")'), kv=KV([['引擎', 'validator/v10,首次使用才创建'], ['tag 名', 'binding(不是 validator)'], ['切片', 'Gin 逐个元素校验']], ['tag 名'])),
    step("一份“全都不合格”的请求体,validator 报了 11 项:Name 的 min=3、Age 的 gte=18、Email、Role 的 oneof(Param 是 \"admin user guest\")、Site 的 url、ID 的 uuid、Tags[1] 的 alpha(dive 下去的元素,Namespace 带下标)、Zip 的 numeric、Birth 的 datetime(Param 是日期布局)、IP 的 ip、Confirm 的 eqfield=Pass。每项是个 FieldError,有 Namespace / Tag / Param / Kind / Value。同一份结构体换成合格的请求体则返回 nil。", t=tl(S(2)), mark=lidx(S(2), 'Req.Tags[1]', 'Req.Confirm', 'Req.Role'), done=lidx(S(2), 'Req.Name', 'Req.Age', 'Req.Email', 'nil(校验通过)'), b=bars([['不合格的字段', 11, '11 项'], ['合格请求', 0, '0 项']], 11, mark=[0], done=[1]), kv=KV([['FieldError', 'Namespace / Tag / Param / Kind / Value'], ['oneof', 'Param 是 "admin user guest"'], ['dive', 'Namespace 带下标 Req.Tags[1]']], ['dive'])),
    step("err.Error() 的原文:多项错误用换行连接,每项是 Key: 'Req.Name' Error:Field validation for 'Name' failed on the 'min' tag。ShouldBindJSON 返回的错误有三类:校验失败是 validator.ValidationErrors;类型不匹配是 *json.UnmarshalTypeError(json: cannot unmarshal string into Go struct field Req.age of type int);JSON 本身坏了是 unexpected EOF 之类的 errorString。", t=tl(S(3)), mark=lidx(S(3), 'validator.ValidationErrors', '*json.UnmarshalTypeError', '*errors.errorString'), done=lidx(S(3), "Key: 'Req.Name'", "Key: 'Req.Age'"), kv=KV([['校验失败', 'validator.ValidationErrors'], ['类型不匹配', '*json.UnmarshalTypeError'], ['JSON 语法错', 'unexpected EOF 等']], ['校验失败'])),
    step("min / max 的含义随类型变:字符串按字符(rune)数,\"你好\" 6 字节 2 字符,min=3 不通过,\"你好吗\" 3 字符通过;整数、浮点数比数值(2 不通过、3 通过、100 通过;2.9 不通过、3.0 通过);切片和 map 比元素个数([]int{1,2} 不通过,{1,2,3} 通过)。", t=tl(S(4)), mark=lidx(S(4), '你好"(6 字节 2 字符)', 'int 2   min=3'), done=lidx(S(4), '[]int{1,2} min=3', 'map 2 个键'), kv=KV([['字符串', '字符数(rune),不是字节数'], ['数字', '比数值'], ['切片 / map', '比元素个数']], ['字符串'])),
    step("嵌套:Order.Addr.City 与指针字段 Ship.City 自动校验;切片元素 Items 没写 dive,里面的 {} 不被检查,Items2 写了 dive 才报 Items2[0].Sku;map 同理(ByKey[k].Sku)。顶层是切片时由 Gin 的 ValidateStruct 逐个校验元素,错误类型是 binding.SliceValidationError,每项带 [下标] 前缀。", t=tl(S(5)), mark=lidx(S(5), 'Order.Items2[0].Sku', 'Order.ByKey[k].Sku', 'binding.SliceValidationError'), done=lidx(S(5), 'Order.Addr.City', 'Order.Ship.City'), kv=KV([['嵌套结构体 / 指针', '自动校验'], ['切片、map 的元素', '必须写 dive'], ['顶层切片', 'SliceValidationError,带 [下标]']], ['切片、map 的元素'])),
]
A = mkartn('n27', 27, 'Gin,validator,参数校验,binding,required,dive,Go,真实验证,动画演示',
    '在 Gin v1.12.0(validator v10.30.1)里实测校验规则:tag 名是 binding;一份全不合格的请求报出 11 项 FieldError;ShouldBindJSON 返回三类错误;min/max 对字符串按字符数、数字比数值、切片比个数;嵌套结构体自动校验,切片和 map 的元素要写 dive。',
    'binding:"required,min=3"、oneof、email、dive……这些规则到底怎么判、报什么错、和字段类型有什么关系?这篇用一份全不合格的请求把常用规则跑一遍,逐个看 FieldError 里的信息,再看错误的三种类型和嵌套、切片的校验边界。',
    [('11 项', '一份全不合格的请求里 validator 报出的字段错误个数'), ('字符数', 'min=3 对 "你好" 不通过:字符串按字符数,而不是字节数'), ('dive', '切片元素的规则要写 dive 才生效(Items 没写,{} 不被检查)')],
    [('用的是什么校验器', '<p>Gin 把 <code>go-playground/validator/v10</code> 包了一层,tag 名改成了 <code>binding</code>,第一次校验时才初始化。顶层是切片时 Gin 自己逐个元素调用校验器;其它非结构体类型直接放行。</p>'),
     ('FieldError 里有什么', '<p>每个失败的字段是一个 <code>FieldError</code>:<code>Namespace()</code>(带结构体名和下标的完整路径,如 <code>Req.Tags[1]</code>)、<code>Tag()</code>、<code>Param()</code>(规则的参数,如 <code>min=3</code> 里的 3、<code>oneof</code> 里的取值列表)、<code>Kind()</code>、<code>Value()</code>。要把校验错误翻译成面向用户的文案,基本就靠 <code>Tag</code> 和 <code>Param</code> 查表。同一个字段多条规则时,第一条失败就停止,只报一项。</p>'),
     ('三种错误', '<p><code>ShouldBindJSON</code> 返回的错误不止校验失败一种:字段类型不对是 <code>*json.UnmarshalTypeError</code>(而且是在校验之前就报错,不会进入校验),JSON 语法错误是普通 error。用 <code>errors.As</code> 判断是不是 <code>validator.ValidationErrors</code>,再决定怎么回应客户端。</p>'),
     ('min 与 max 的含义', '<p>同一条规则对不同类型含义不同:字符串数的是字符(rune)个数,不是字节数,所以中文 “你好” 只算 2;整数、浮点数比较数值;切片和 map 比较元素个数。<code>len</code>、<code>eq</code> 等也是同样的规则。</p>'),
     ('嵌套、切片、map', '<p>嵌套的结构体字段(含指针)会自动校验;切片和 map 里的元素必须在字段上加 <code>dive</code>,否则里面的 <code>required</code> 等规则不会被检查——这是最常见的“规则写了却没生效”。顶层切片则由 Gin 逐个校验,错误类型是 <code>SliceValidationError</code>,每项带 <code>[下标]</code> 前缀。</p>')],
    steps,
    [ENV_N_GIN + '。校验器是 Gin 内置的 validator v10.30.1(go-playground);请求用 httptest 直接调用 ServeHTTP;第四节直接用 validator.New() 并 SetTagName("binding"),规则含义与 Gin 内置的一致;每种情形各一次',
     '没有验证:validator 的所有内置规则(只试了约 15 个常见规则);错误信息的多语言翻译(universal-translator);跨字段规则 required_if、required_with 等;性能(每次校验的耗时与分配);并发调用时的缓存行为'],
    '校验规则')
